UPDATE `BOT_LETTER`
SET is_read = TRUE, read_at = NOW()
WHERE letter_id = #{letterId} AND user_id = #{userId}

UPDATE `USER_BOT_RELATION`
SET intimacy_score = intimacy_score + #{expGain}
WHERE user_id = #{userId}

